const cfg = $json;

if (typeof cfg.projectDirectory !== 'string' || !cfg.projectDirectory.startsWith('/')) {
  throw new Error('projectDirectory must be an absolute path visible inside n8n.');
}
if (/[\r\n\0]/.test(cfg.projectDirectory)) {
  throw new Error('projectDirectory contains an unsafe character.');
}
if (typeof cfg.batchFile !== 'string' || !/^data\/[A-Za-z0-9][A-Za-z0-9._-]*\.csv$/.test(cfg.batchFile)) {
  throw new Error('batchFile must look like data/batch-name.csv and cannot traverse directories.');
}
if (typeof cfg.runId !== 'string' || !/^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$/.test(cfg.runId)) {
  throw new Error('runId must match the Python machine safety rule.');
}

const shellQuote = (value) => `'${String(value).replace(/'/g, `'\"'\"'`)}'`;
const noLlm = cfg.useLlm === true ? '' : ' --no-llm';
const command = [
  'cd', shellQuote(cfg.projectDirectory), '&&',
  'python3 -m machine.run',
  '--batch', shellQuote(cfg.batchFile),
  '--run-id', shellQuote(cfg.runId),
  noLlm,
].join(' ').trim();

return { json: { ...cfg, command } };

let metrics;
try {
  metrics = JSON.parse($json.stdout);
} catch (error) {
  throw new Error(`The Python machine did not return valid JSON metrics: ${error.message}`);
}

const violations = [];
if (metrics.send_mode !== false) violations.push('send_mode is not false');
if (metrics.emails_sent !== 0) violations.push('emails_sent is not zero');
if (metrics.drafts_written !== metrics.batch_size) violations.push('not every batch row produced a draft');
if (metrics.claim_check_failures !== 0) violations.push('one or more drafts failed claim checking');

if (violations.length) {
  throw new Error(`Task 1 safety/quality gate failed: ${violations.join('; ')}`);
}

return {
  json: {
    status: 'PASS',
    message: `Created ${metrics.drafts_written} draft-only messages. Sent 0.`,
    runId: metrics.run_id,
    batchFile: metrics.batch_file,
    draftsWritten: metrics.drafts_written,
    emailsSent: metrics.emails_sent,
    claimCheckFailures: metrics.claim_check_failures,
    rowsWithRiskFlags: metrics.rows_with_risk_flags,
    generators: metrics.generators,
    docPains: metrics.doc_pains,
    outputLocations: {
      drafts: `outbox/${metrics.run_id}/`,
      evidence: `runs/${metrics.run_id}/`
    },
    rawMetrics: metrics
  }
};
